namespace Contracts.Desktop.Reporting;

using Contracts.Application.Reporting;
using Contracts.Desktop.Dashboard;
using Contracts.Desktop.Okr;

public sealed record ReportKindOption(ReportKind Kind,string Title);
public enum ReportTab{General,Financial,Kpi,Okr}
public sealed class ReportPageViewModel:ObservableObject,INavigationTarget
{
    private readonly ReportingQueryService query;private readonly ReportingExportService export;private readonly ReportHtmlRenderer renderer;private readonly IReportFileDialogService files;private readonly IPersianDateService dates;
    private ReportKindOption selected;private IReadOnlyList<ReportKindOption> kinds;private string from="",to="",html="",error="";private bool busy;private long? contractTypeId,statusId,partyId,projectId;private ReportDocument? document;private ReportTab tab;
    public ReportPageViewModel(ReportingQueryService query,ReportingExportService export,ReportHtmlRenderer renderer,IReportFileDialogService files,IPersianDateService dates,DashboardPageViewModel dashboard,OkrPageViewModel okr)
    {this.query=query;this.export=export;this.renderer=renderer;this.files=files;this.dates=dates;Dashboard=dashboard;Okr=okr;kinds=GeneralOptions;selected=kinds[0];GenerateCommand=new AsyncRelayCommand(GenerateAsync);ExportCsvCommand=new AsyncRelayCommand(ct=>ExportAsync(ReportExportFormat.Csv,ct));ExportXlsxCommand=new AsyncRelayCommand(ct=>ExportAsync(ReportExportFormat.Xlsx,ct));ExportPdfCommand=new AsyncRelayCommand(ExportPdfAsync);SelectGeneralCommand=new AsyncRelayCommand(ct=>SelectTabAsync(ReportTab.General,ct));SelectFinancialCommand=new AsyncRelayCommand(ct=>SelectTabAsync(ReportTab.Financial,ct));SelectKpiCommand=new AsyncRelayCommand(ct=>SelectTabAsync(ReportTab.Kpi,ct));SelectOkrCommand=new AsyncRelayCommand(ct=>SelectTabAsync(ReportTab.Okr,ct));}
    public IReadOnlyList<ReportKindOption> Kinds{get=>kinds;private set=>SetProperty(ref kinds,value);}public ReportKindOption SelectedKind{get=>selected;set=>SetProperty(ref selected,value);}public string DateFrom{get=>from;set=>SetProperty(ref from,value);}public string DateTo{get=>to;set=>SetProperty(ref to,value);}public long? ContractTypeId{get=>contractTypeId;set=>SetProperty(ref contractTypeId,value);}public long? ContractStatusId{get=>statusId;set=>SetProperty(ref statusId,value);}public long? PartyId{get=>partyId;set=>SetProperty(ref partyId,value);}public long? ProjectId{get=>projectId;set=>SetProperty(ref projectId,value);}public string Html{get=>html;private set=>SetProperty(ref html,value);}public string ErrorMessage{get=>error;private set{if(SetProperty(ref error,value))OnPropertyChanged(nameof(HasError));}}public bool HasError=>!string.IsNullOrEmpty(error);public bool IsBusy{get=>busy;private set=>SetProperty(ref busy,value);}public bool IsKpi=>tab==ReportTab.Kpi;public bool IsOkr=>tab==ReportTab.Okr;public bool IsReport=>!IsKpi&&!IsOkr;public DashboardPageViewModel Dashboard{get;}public OkrPageViewModel Okr{get;}
    public IAsyncRelayCommand GenerateCommand{get;}public IAsyncRelayCommand ExportCsvCommand{get;}public IAsyncRelayCommand ExportXlsxCommand{get;}public IAsyncRelayCommand ExportPdfCommand{get;}public IAsyncRelayCommand SelectGeneralCommand{get;}public IAsyncRelayCommand SelectFinancialCommand{get;}public IAsyncRelayCommand SelectKpiCommand{get;}public IAsyncRelayCommand SelectOkrCommand{get;}
    public void ActivateKpi(){SetTab(ReportTab.Kpi);Dashboard.ActivateRoute("kpi");}
    public void ActivateOkr()=>SetTab(ReportTab.Okr);
    public Task OnNavigatedToAsync(CancellationToken cancellationToken)=>IsKpi?Dashboard.OnNavigatedToAsync(cancellationToken):IsOkr?Okr.OnNavigatedToAsync(cancellationToken):GenerateAsync(cancellationToken);
    private async Task GenerateAsync(CancellationToken ct)=>await Run(async()=>{document=await query.ExecuteAsync(new(SelectedKind.Kind,Parse(DateFrom),Parse(DateTo),ContractTypeId,ContractStatusId,PartyId,ProjectId),ct);Html=renderer.Render(document);});
    private async Task ExportAsync(ReportExportFormat format,CancellationToken ct){if(document is null)return;string? path=files.Save(format);if(path is null)return;await Run(()=>export.ExportAsync(new(document,format,path),ct));}
    private async Task ExportPdfAsync(CancellationToken ct){if(document is null)return;string? path=files.SavePdf();if(path is null)return;await Run(()=>export.ExportAsync(new(document,ReportExportFormat.Pdf,path),ct));}
    private DateOnly? Parse(string value){if(string.IsNullOrWhiteSpace(value))return null;if(dates.TryParse(value,out DateOnly date))return date;throw new ArgumentException("تاریخ باید شمسی و به شکل yyyy/MM/dd باشد.");}
    private async Task Run(Func<Task> action){IsBusy=true;ErrorMessage="";try{await action();}catch(OperationCanceledException){throw;}catch(Exception){ErrorMessage="تولید یا خروجی گزارش ناموفق بود. فیلترها و مسیر خروجی را بررسی کنید.";}finally{IsBusy=false;}}
    private async Task SelectTabAsync(ReportTab value,CancellationToken ct){SetTab(value);if(value==ReportTab.Kpi){Dashboard.ActivateRoute("kpi");await Dashboard.OnNavigatedToAsync(ct);}else if(value==ReportTab.Okr)await Okr.OnNavigatedToAsync(ct);else await GenerateAsync(ct);}
    private void SetTab(ReportTab value){tab=value;Kinds=value==ReportTab.Financial?FinancialOptions:GeneralOptions;SelectedKind=Kinds[0];OnPropertyChanged(nameof(IsKpi));OnPropertyChanged(nameof(IsOkr));OnPropertyChanged(nameof(IsReport));}
    private static readonly ReportKindOption[] GeneralOptions=[new(ReportKind.GeneralContracts,"عمومی قراردادها"),new(ReportKind.Guarantees,"ضمانت‌نامه‌ها"),new(ReportKind.ExpiringContracts,"قراردادهای رو به انقضا"),new(ReportKind.ContractorEvaluation,"ارزیابی پیمانکار"),new(ReportKind.Invoices,"صورتحساب‌ها"),new(ReportKind.Amendments,"الحاقیه‌ها"),new(ReportKind.Documents,"اسناد"),new(ReportKind.Alerts,"هشدارها")];
    private static readonly ReportKindOption[] FinancialOptions=[new(ReportKind.PurchaseBySupplier,"خرید به تفکیک تأمین‌کننده"),new(ReportKind.SalesByCustomer,"فروش به تفکیک مشتری"),new(ReportKind.OutsourceByContractor,"برون‌سپاری به تفکیک پیمانکار"),new(ReportKind.Payments,"پرداخت‌ها"),new(ReportKind.Receipts,"دریافت‌ها"),new(ReportKind.ProjectFinance,"مالی پروژه")];
}
